import { test, expect } from '@playwright/test';

test.describe('File Upload Cancellation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/upload');
  });

  test('should allow user to cancel an in-progress upload', async ({ page }) => {
    const filePath = 'path/to/file.txt';
    await page.setInputFiles('input[type="file"]', filePath);
    await expect(page.getByText('Uploading...')).toBeVisible();

    await page.getByRole('button', { name: 'Cancel Upload' }).click();
    await expect(page.getByText('Upload cancelled')).toBeVisible();
  });

  test('should not show upload progress after cancellation', async ({ page }) => {
    const filePath = 'path/to/file.txt';
    await page.setInputFiles('input[type="file"]', filePath);
    await expect(page.getByText('Uploading...')).toBeVisible();

    await page.getByRole('button', { name: 'Cancel Upload' }).click();
    await expect(page.getByText('Uploading...')).not.toBeVisible();
  });
});
